-- How BIT_COUNT reads a string as an integer, by expression (column of a table, of a
-- derived table, of a view, literal, function, variable) and by version; the sign of
-- the integer read, CAST(x AS SIGNED) and CAST(x AS UNSIGNED); large decimals by expression.
DROP TABLE IF EXISTS bf;
CREATE TABLE bf (id INT PRIMARY KEY, s VARCHAR(40), c CHAR(30), t TEXT);
INSERT INTO bf VALUES (1, '18446744073709551615', '18446744073709551615', '18446744073709551615'), (2, '9223372036854775808', '9223372036854775808', '9223372036854775808'), (3, CONCAT(CHAR(9), '-1'), CONCAT(CHAR(9), '-1'), CONCAT(CHAR(9), '-1')), (4, CONCAT(CHAR(10), '-1'), '', ''), (5, CONCAT(CHAR(11), '-1'), '', ''), (6, CONCAT(CHAR(12), '-1'), '', ''), (7, CONCAT(CHAR(13), '-1'), '', ''), (8, '18446744073709551615e-400', '', ''), (9, CONCAT(CHAR(9), '18446744073709551615'), '', ''), (10, '+18446744073709551615', '', '');
SELECT id, BIT_COUNT(s) AS s, BIT_COUNT(c) AS c, BIT_COUNT(t) AS t, BIT_COUNT(CONCAT(s)) AS concat, BIT_COUNT(LOWER(s)) AS lower_, BIT_COUNT(TRIM(s)) AS trim_, BIT_COUNT(IF(id > 0, s, s)) AS if_, BIT_COUNT(COALESCE(s, s)) AS coalesce_, BIT_COUNT(IFNULL(s, '')) AS ifnull_, BIT_COUNT(CASE WHEN id > 0 THEN s END) AS case_, BIT_COUNT(CAST(s AS CHAR)) AS cast_char, BIT_COUNT(s COLLATE utf8mb4_bin) AS collate_, BIT_COUNT(CONVERT(s USING latin1)) AS convert_, BIT_COUNT(SUBSTRING(s, 1)) AS substring_, BIT_COUNT(REPLACE(s, 'x', 'y')) AS replace_, CAST(s AS SIGNED) AS signed_, s > 0 AS positive FROM bf ORDER BY id;
SELECT BIT_COUNT(CONCAT('18446744073709551615')) AS concat_lit, BIT_COUNT(CONCAT('1844', '6744073709551615')) AS concat2, BIT_COUNT(LOWER('18446744073709551615')) AS lower_lit, BIT_COUNT(_utf8mb4'18446744073709551615') AS introducer, BIT_COUNT('18446744073709551615' COLLATE utf8mb4_bin) AS collate_lit, BIT_COUNT(IF(TRUE, '18446744073709551615', '')) AS if_lit, BIT_COUNT(N'18446744073709551615') AS national, BIT_COUNT('1844' '6744073709551615') AS adjacent;
SET @v = '18446744073709551615';
SELECT BIT_COUNT(@v) AS var, BIT_COUNT((SELECT '18446744073709551615')) AS subquery_lit, BIT_COUNT(CONCAT(@v)) AS concat_var;
SELECT BIT_COUNT(x) AS derived FROM (SELECT '18446744073709551615' AS x) AS q;
SELECT BIT_COUNT(CONCAT(CHAR(9), '-1')) AS tab_lit, BIT_COUNT('18446744073709551615e-400') AS underflow_lit, BIT_COUNT(' -1') AS space_lit, BIT_COUNT('+18446744073709551615') AS plus_lit;
SELECT id, BIT_COUNT(x) AS concat_derived, BIT_COUNT(y) AS coalesce_derived, BIT_COUNT(z) AS literal_derived FROM (SELECT id, CONCAT(s) AS x, COALESCE(s, s) AS y, '18446744073709551615' AS z FROM bf) AS q WHERE id <= 2 ORDER BY id;
WITH c AS (SELECT id, CONCAT(s) AS x, COALESCE(s, s) AS y FROM bf) SELECT id, BIT_COUNT(x) AS concat_cte, BIT_COUNT(y) AS coalesce_cte FROM c WHERE id <= 2 ORDER BY id;
SELECT BIT_COUNT(x) AS union_derived FROM (SELECT '18446744073709551615' AS x UNION ALL SELECT '9223372036854775808') AS q;
SELECT id, BIT_COUNT(x) AS grouped FROM (SELECT id, MAX(CONCAT(s)) AS x FROM bf GROUP BY id) AS q WHERE id <= 2 ORDER BY id;
DROP VIEW IF EXISTS bv;
CREATE VIEW bv AS SELECT id, CONCAT(s) AS x, s FROM bf;
SELECT id, BIT_COUNT(x) AS concat_view, BIT_COUNT(s) AS view_column FROM bv WHERE id <= 2 ORDER BY id;
SELECT bf.id, BIT_COUNT(bf.s) AS joined FROM bf JOIN bf AS b2 ON b2.id = bf.id WHERE bf.id <= 2 ORDER BY bf.id;
SELECT id, BIT_COUNT(s) AS grouped_column FROM bf WHERE id <= 2 GROUP BY id, s ORDER BY id;
SELECT BIT_COUNT(MAX(s)) AS max_column FROM bf WHERE id = 1;
DROP TABLE IF EXISTS bl;
CREATE TABLE bl (id INT PRIMARY KEY, s VARCHAR(40));
INSERT INTO bl VALUES (1, '9223372036854775807'), (2, '9223372036854775808'), (3, '18446744073709551615'), (4, '18446744073709551616'), (5, '99999999999999999999'), (6, '-9223372036854775808'), (7, '-9223372036854775809'), (8, '-99999999999999999999'), (9, '1e19'), (10, '9.3e18'), (11, ' 18446744073709551615'), (12, '18446744073709551615.5'), (13, '12345678901234567890'), (14, '0x10'), (15, '1.8e19'), (16, '2e19');
SELECT id, s, BIT_COUNT(s) AS col, CAST(s AS SIGNED) AS col_signed FROM bl ORDER BY id;
SELECT BIT_COUNT('9223372036854775807') AS l1, BIT_COUNT('9223372036854775808') AS l2, BIT_COUNT('18446744073709551615') AS l3, BIT_COUNT('18446744073709551616') AS l4, BIT_COUNT('99999999999999999999') AS l5, BIT_COUNT('-9223372036854775808') AS l6, BIT_COUNT('-9223372036854775809') AS l7, BIT_COUNT('-99999999999999999999') AS l8;
SELECT BIT_COUNT('1e19') AS l9, BIT_COUNT('9.3e18') AS l10, BIT_COUNT(' 18446744073709551615') AS l11, BIT_COUNT('18446744073709551615.5') AS l12, BIT_COUNT('12345678901234567890') AS l13, BIT_COUNT('0x10') AS l14, BIT_COUNT('1.8e19') AS l15, BIT_COUNT('2e19') AS l16;
SELECT CAST('9223372036854775808' AS SIGNED) AS c2, CAST('18446744073709551615' AS SIGNED) AS c3, CAST('18446744073709551616' AS SIGNED) AS c4, CAST('99999999999999999999' AS SIGNED) AS c5, CAST('-9223372036854775809' AS SIGNED) AS c7, CAST('12345678901234567890' AS SIGNED) AS c13, CAST('1e19' AS SIGNED) AS c9;
SELECT BIT_COUNT(CONCAT('18446744073709551615')) AS f1, BIT_COUNT(CONCAT('9223372036854775808')) AS f2, BIT_COUNT(LOWER('18446744073709551615')) AS f3, BIT_COUNT(s) AS sub FROM bl WHERE id = 3;
SELECT BIT_COUNT((SELECT s FROM bl WHERE id = 3)) AS q3, BIT_COUNT((SELECT s FROM bl WHERE id = 2)) AS q2;
DROP TABLE IF EXISTS bs;
CREATE TABLE bs (id INT PRIMARY KEY, s VARCHAR(40));
INSERT INTO bs VALUES (1, '-1'), (2, '-9223372036854775809'), (3, '18446744073709551615'), (4, '18446744073709551616'), (5, CONCAT(_utf8mb4 X'C2A0', '-1')), (6, CONCAT(_utf8mb4 X'C2A0', '18446744073709551615')), (7, '-1e-400'), (8, '18446744073709551615e-400'), (9, CONCAT(CHAR(11 USING utf8mb4), '-1')), (10, CONCAT(CHAR(11 USING utf8mb4), '9223372036854775808')), (11, ''), (12, '-'), (13, '- 1'), (14, '+-1'), (15, '0x8000000000000000'), (16, '  +9223372036854775808  ');
SELECT id, BIT_COUNT(s) AS b, CAST(s AS SIGNED) AS sg, CAST(s AS UNSIGNED) AS us, s REGEXP '^[[:space:]]*-' AS neg_re, s > 0 AS pos FROM bs ORDER BY id;
SELECT BIT_COUNT(_utf8mb4 X'0A2D31') AS lf, BIT_COUNT(_utf8mb4 X'0B2D31') AS vt, BIT_COUNT(_utf8mb4 X'0D2D31') AS cr, BIT_COUNT(_utf8mb4 X'092D31') AS tab, BIT_COUNT(_utf8mb4 X'C2A02D31') AS nbsp, BIT_COUNT('-1e-400') AS neg_underflow, BIT_COUNT('18446744073709551615e-400') AS underflow, BIT_COUNT('1.5e3') AS exp_, BIT_COUNT('0x10') AS hex_, BIT_COUNT('  +9223372036854775808  ') AS plus_;
SELECT CAST(_utf8mb4 X'0A2D31' AS SIGNED) AS lf, CAST(_utf8mb4 X'0B2D31' AS SIGNED) AS vt, CAST(_utf8mb4 X'092D31' AS SIGNED) AS tab, CAST(_utf8mb4 X'C2A02D31' AS SIGNED) AS nbsp, CAST('-1e-400' AS SIGNED) AS neg_underflow, CAST('1.5e3' AS SIGNED) AS exp_;
DROP TABLE IF EXISTS bd;
CREATE TABLE bd (id INT PRIMARY KEY, de DECIMAL(25, 1));
INSERT INTO bd VALUES (1, 9223372036854775808), (2, 18446744073709551615), (3, 18446744073709551616), (4, -9223372036854775809), (5, 99999999999999999999), (6, 9223372036854775807.5);
SELECT id, BIT_COUNT(de) AS col, BIT_COUNT(COALESCE(de, de)) AS coalesce_, BIT_COUNT(IF(id > 0, de, de)) AS if_, BIT_COUNT(de + 0) AS plus, BIT_COUNT(-(-de)) AS neg, BIT_COUNT(ROUND(de)) AS round_, BIT_COUNT(CAST(de AS DECIMAL(30, 0))) AS cast_, BIT_COUNT(x) AS derived FROM bd JOIN (SELECT id AS k, de * 1 AS x FROM bd) AS q ON q.k = bd.id ORDER BY id;
SELECT BIT_COUNT(9223372036854775808) AS l1, BIT_COUNT(18446744073709551616) AS l3, BIT_COUNT(-9223372036854775809) AS l4, BIT_COUNT(9223372036854775807.5) AS l6, BIT_COUNT(18446744073709551615.0) AS l2;
SELECT BIT_COUNT(x) AS derived_literal FROM (SELECT 18446744073709551616 AS x) AS q;
SET @d = CAST(18446744073709551616 AS DECIMAL(25, 0));
SELECT BIT_COUNT(@d) AS var;
